"""Output-only recovery after CSV schema error. Never calls provider/solver/generator/inference."""
from t2_tilt_g0_core import ROOT,OUT,LOCAL,RES,sha,read,rows,dump,table,utc
import numpy as np,shutil,json,time

def main():
 if (OUT/'OUTPUT_RECOVERY.json').exists():raise RuntimeError('recovery already delivered')
 assert (OUT/'EXECUTION_FAILURE.json').exists()
 assert not (OUT/'CALIBRATION_GENERATION_STARTED.json').exists() and not (OUT/'TEST_GENERATION_STARTED.json').exists()
 original=OUT/'FORWARD_CONTROLS.csv';shutil.copyfile(original,OUT/'FORWARD_CONTROLS_ORIGINAL_PARTIAL.csv');shutil.copyfile(LOCAL/'t2_tilt_g0_forward.py.log',OUT/'ORIGINAL_EXECUTION_EXCEPTION.log')
 files=[p for p in LOCAL.rglob('*') if p.is_file()];source=[p for p in OUT.iterdir() if p.is_file() and p.name in ['FORWARD_CATALOGUE_NUMERICAL_STABILITY.csv','FIELD_CONTROLS.csv','PROVIDER_MODE_WINDOW_AND_MESH.csv','SOLVER_CALLS.csv','FORWARD_CONTROLS_ORIGINAL_PARTIAL.csv','ORIGINAL_EXECUTION_EXCEPTION.log']]
 seal={str(p):sha(p) for p in files+source};dump(OUT/'OUTPUT_RECOVERY_INPUT_SEAL.json',{'utc':utc(),'files':seal,'purpose':'seal original raw completed outputs before read-only reporting recovery','no_saved_inputs_mutated':True})
 fields=rows(OUT/'FIELD_CONTROLS.csv');combined=[]
 for r in fields:combined.append({'control':r['control'],'resource':'A0_0+A_P4M+B1_V4','mesh':160001,'frequency_hz':r['frequency_hz'],'error':float(r['error']),'limit':.002,'PASS':r['PASS']=='True','evidence':'original FIELD_CONTROL, single scalar per frequency'})
 for res in RES:
  a=np.load(LOCAL/'replicas'/f'CAL_{res}_n160001.npy');b=np.load(LOCAL/'replicas'/f'CAL_{res}_n80001.npy');c=np.sum(b.conj()*a,axis=-1)/np.sum(abs(b)**2,axis=-1);e=float(np.max(np.sqrt(np.sum(abs(a-c[...,None]*b)**2,axis=-1)/np.sum(abs(a)**2,axis=-1))));combined.append({'control':'independent_calibration_geometry_crossmesh','resource':res,'mesh':'80001_vs160001','frequency_hz':'all3','error':e,'limit':.002,'PASS':e<=.002,'evidence':'original saved CAL fields, no recomputation of physical fields'})
 coords=rows(OUT/'ARRAY_GEOMETRY_TABLE.csv')
 for mesh in [80001,160001]:
  for res in RES:
   y=[float(r['y_m']) for r in coords if r['resource']==res];e=max(abs(v) for v in y);combined.append({'control':'theta_sign_mirror_all_resources','resource':res,'mesh':mesh,'frequency_hz':'all3','error':e,'limit':0,'PASS':e==0,'evidence':'analytic exact rho(theta)=rho(-theta) for y=0, nominal horizontal isotropy; independently cold verified at registered catalogue states'})
  for cat in ['primary','fine']:
   a=np.load(LOCAL/'replicas'/f'A0_0_{cat}_n{mesh}.npy');b=np.load(LOCAL/'replicas'/f'B1_V4_{cat}_n{mesh}.npy');d=np.load(LOCAL/'replicas'/f'B2_DUP_{cat}_n{mesh}.npy');e=max(float(np.max(abs(a-b[:,:,:8]))),float(np.max(abs(a-d[:,:,:8]))),float(np.max(abs(d[:,:,8:]-a[:,:,3,None]))));combined.append({'control':'shared_original8_and_DUP_pressure','resource':'B1_B2_A0','mesh':mesh,'frequency_hz':'all3','error':e,'limit':1e-12,'PASS':e<=1e-12,'evidence':f'original saved full {cat} replicas, stronger than3 original symmetry control points'})
 table(OUT/'FORWARD_CONTROLS.csv',combined);num=rows(OUT/'FORWARD_CATALOGUE_NUMERICAL_STABILITY.csv');passed=all(r['PASS'] for r in combined) and all(r['PASS']=='True' for r in num);assert not passed
 dump(OUT/'FORWARD_DECISION.json',{'utc':utc(),'admitted':False,'status':'FORWARD_NUMERIC_NOT_ADMITTED','CHIGH':'CONDITIONAL_MODAL_WINDOW_LIMIT','new_KRAKEN':6,'new_FIELD':3,'max_cross_mesh_profiled_error':max(float(r['max_profiled_shape_error']) for r in num),'max_FIELD_profiled_error':max(float(r['error']) for r in fields),'failed_catalogue_frequency_controls':sum(r['PASS']!='True' for r in num),'failed_other_controls':sum(not r['PASS'] for r in combined),'full_catalogue_states_checked':sum(int(r['candidates']) for r in num),'calibration_test_MC_allowed':False,'interpolation':'NONE_DIRECT_ALL_MODE_SUM','science_wall_s':read(OUT/'EXECUTION_FAILURE.json')['science_wall_s'],'output_only_recovery':True,'original_failure_retained':True,'original_frozen_code_not_modified':True})
 dump(OUT/'REPLICA_FREEZE.json',{'utc':utc(),'files':{p.name:sha(p) for p in (LOCAL/'replicas').glob('*.npy')},'complete_raw_shape_differences':{p.name:sha(p) for p in LOCAL.glob('SHAPE_ERROR*.npy')},'main_data_not_generated_yet':True,'sealed_after_original_reporting_exception_before_recovery':True})
 dump(OUT/'DECISION.json',{'stage':'T2-TILT-G0','status':'FORWARD_NUMERIC_NOT_ADMITTED','A':'NOT_EVALUATED','B':'NOT_EVALUATED','primary_geometry_counts':{'A':'NOT_EVALUATED','B':'NOT_EVALUATED','denominator':3},'calibration_records_executed':0,'planned_calibration_base_records':256,'test_base_innovations_executed':0,'test_resource_configs_executed':0,'planned_test_resource_configs':5184,'main_inference':'NOT_EVALUATED','propagation_status':'CONDITIONAL_MODAL_WINDOW_LIMIT','original_H3_P0_P1_SP1_RX_AUX_gate_unchanged':True,'output_only_recovery':True,'R4_percent':0,'research_lead_audit':'PENDING','state':'STOP','next_stage_authorized':False})
 for path,expected in seal.items():assert sha(path)==expected,path
 dump(OUT/'OUTPUT_RECOVERY.json',{'utc':utc(),'original_failure':'CSV DictWriter mixed field schemas after all6KRAKEN/3FIELD/both full catalogues/CALfields, before forward decision and any MC','original_code_sha256':sha(ROOT/'t2_tilt_g0_forward.py'),'recovery_code_sha256':sha(ROOT/'t2_tilt_g0_output_recovery.py'),'source_seal_sha256':sha(OUT/'OUTPUT_RECOVERY_INPUT_SEAL.json'),'changes':'restore missing reporting aggregation from stored arrays, replace partial CSV, seal existing outputs; symmetry analytic proof and stored shared channels; frozen tolerances unchanged','new_solver_MC_signal_DFT_inference_or_optimization':0,'all_sealed_sources_unchanged':True,'science_failure_scope':'reporting schema exception; independently observed forward numeric nonadmission remains','STOP':True})
 print('OUTPUT ONLY RECOVERY: gate NOT_ADMITTED; MC=0; all sealed raw sources unchanged',flush=True)
if __name__=='__main__':main()